def nb_successeurs(m, i):
    nb = 0
    for j in range(len(m)):
        if m[i][j] == 1:
            nb = nb + 1
    return nb

def places_libres(salle):
    libres = 0
    for r in range(len(salle)):
        for p in range(len(salle[r])):
            if not salle[r][p]:
                libres = libres + 1
    return libres
